func (q *Queries) RenameFileNamespaceEntry(ctx context.Context, arg *RenameFileNamespaceEntryParams) (*NamespaceEntry, error) {
	row := q.db.QueryRow(ctx, renameFileNamespaceEntry,
		arg.Name,
		arg.NormalizedName,
		arg.UpdatedAt,
		arg.NamespaceEntryID,
		arg.RowVersion,
	)
	var i NamespaceEntry
	err := row.Scan(
		&i.NamespaceEntryID,
		&i.SpaceID,
		&i.ParentFolderID,
		&i.EntryType,
		&i.Name,
		&i.NormalizedName,
		&i.PathCache,
		&i.Depth,
		&i.LifecycleStatus,
		&i.CreatedByUserID,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.RowVersion,
	)
	return &i, err
}

