const updateFileDescendantPaths = `-- name: UpdateFileDescendantPaths :exec
WITH RECURSIVE tree AS (
  SELECT child.namespace_entry_id,
         $2::text || '/' || child.name AS new_path,
         $3::integer + 1 AS new_depth
  FROM namespace_entries child
  WHERE child.parent_folder_id = $4::uuid
  UNION ALL
  SELECT child.namespace_entry_id,
         tree.new_path || '/' || child.name AS new_path,
         tree.new_depth + 1 AS new_depth
  FROM namespace_entries child
  JOIN tree ON child.parent_folder_id = tree.namespace_entry_id
)
UPDATE namespace_entries e
SET path_cache = tree.new_path,
    depth = tree.new_depth,
    updated_at = $1::timestamptz,
    row_version = e.row_version + 1
FROM tree
WHERE e.namespace_entry_id = tree.namespace_entry_id
`

type UpdateFileDescendantPathsParams struct {
	UpdatedAt pgtype.Timestamptz
	RootPath  string
	RootDepth int32
	RootID    pgtype.UUID
}

func (q *Queries) UpdateFileDescendantPaths(ctx context.Context, arg *UpdateFileDescendantPathsParams) error {
	_, err := q.db.Exec(ctx, updateFileDescendantPaths,
		arg.UpdatedAt,
		arg.RootPath,
		arg.RootDepth,
		arg.RootID,
	)
	return err
}

